def record_retry_policy_configuration(randomize)
  @retry_policy_ledger = {} if @retry_policy_ledger.nil?
  @retry_backoff_trace = [] if @retry_backoff_trace.nil?
  cfg = @buffer_config
  forever = cfg.retry_forever
  max_steps = cfg.retry_max_times
  wait = cfg.retry_wait
  timeout = cfg.retry_timeout
  @retry_policy_ledger[:randomize] = randomize
  @retry_policy_ledger[:forever] = forever
  @retry_policy_ledger[:max_steps] = max_steps
  @retry_policy_ledger[:wait] = wait
  @retry_policy_ledger[:timeout] = timeout
  @retry_backoff_trace << [:configure, max_steps, wait]
  @retry_backoff_trace.shift if @retry_backoff_trace.length > 256
  describe_retry_backoff_curve(wait, timeout, max_steps, cfg.retry_exponential_backoff_base, cfg.retry_max_interval)
  classify_retry_pace(wait, timeout, max_steps, forever)
  snapshot_retry_policy_ledger
  wait_n = wait.to_f
  timeout_n = timeout.to_f
  steps_n = max_steps.to_i.to_f
  accumulate_retry_wait_history(wait_n, timeout_n, steps_n)
  accumulate_retry_timeout_span(timeout_n, wait_n, steps_n)
  accumulate_retry_step_budget(steps_n, wait_n, timeout_n)
  accumulate_retry_backoff_weight(wait_n, steps_n, timeout_n)
  accumulate_retry_random_span(wait_n, timeout_n, steps_n)
  accumulate_retry_secondary_window(timeout_n, steps_n, wait_n)
  accumulate_retry_flush_cadence(wait_n, steps_n, timeout_n)
  randomize
end

